import java.util.*;

public class Main {

    // 处理所有询问，返回每次询问的结果
    public static List<int[]> solve(int n, int[] arr, int[][] queries) {
        // pre[i][d] 表示前 i 个数中数字 d 出现的次数
        int[][] pre = new int[n + 1][10];

        for (int i = 1; i <= n; i++) {
            // 先继承前一个位置的统计结果
            for (int d = 0; d < 10; d++) {
                pre[i][d] = pre[i - 1][d];
            }
            // 当前数字出现次数加一
            pre[i][arr[i - 1]]++;
        }

        // 预处理个位映射
        int[][] trans = new int[10][10];
        for (int k = 0; k < 10; k++) {
            for (int d = 0; d < 10; d++) {
                trans[k][d] = (d * k) % 10;
            }
        }

        List<int[]> res = new ArrayList<>();

        for (int[] query : queries) {
            int l = query[0];
            int r = query[1];
            int k = query[2] % 10;

            int[] ans = new int[10];

            // 统计区间内原始数字，再映射到结果中
            for (int d = 0; d < 10; d++) {
                int cnt = pre[r][d] - pre[l - 1][d];
                ans[trans[k][d]] += cnt;
            }

            res.add(ans);
        }

        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        int q = sc.nextInt();
        int[][] queries = new int[q][3];
        for (int i = 0; i < q; i++) {
            queries[i][0] = sc.nextInt();
            queries[i][1] = sc.nextInt();
            queries[i][2] = sc.nextInt();
        }

        List<int[]> res = solve(n, arr, queries);

        StringBuilder sb = new StringBuilder();
        for (int[] row : res) {
            for (int i = 0; i < 10; i++) {
                if (i > 0) sb.append(" ");
                sb.append(row[i]);
            }
            sb.append("\n");
        }

        System.out.print(sb.toString());
        sc.close();
    }
}
